          "এমন সময়ে হঠাৎ পায়ের মৃদু শব্দে সে চমকে পেছনে ফিরে তাকাল। সেখানে দাঁড়িয়ে ছিল মেঘের। তার মুখে ছিল এক রাশ দ্বিধা আর চোখে এক অপার্থিব প্রশ্ন। সে ধীর পায়ে এগিয়ে এসে কাঁপা গলায় বলল, \"তাহমিনা, তুমি কি সত্যি বিশ্বাস করো যে নিয়তি আমাদের নিয়ে যে খেলা খেলছে, তা থেকে পালানোর কোনো পথ আছে?\"",
