          "বাতাসে তখন সোঁদা মাটির ঘ্রাণ ভেসে আসছিল। দূরে নদীর বাঁকে পালতোলা একখানা নৌকা তখন ধীরে ধীরে কুয়াশার ভেতর মিলিয়ে যাচ্ছিল। ঠিক সেই মুহূর্তে ঘরের কোণে থাকা ঘড়িটিতে ঢং ঢং করে বারোটার ঘণ্টা বেজে উঠল। প্রতিটি ঘণ্টার শব্দে ঘরের মধ্যকার নিস্তব্ধতা যেন আরও দ্বিগুণ ভারী হয়ে চেপে বসল।",
          "হঠাৎ করেই দরজায় সশব্দে কড়া নাড়ার শব্দ হলো। উপস্থিত দুইজনেই চমকে দরজার দিকে দৃষ্টি ফেরাল। সেখানে ভিজে একাকার হয়ে এসে দাঁড়িয়েছে শফিক সাহেব। তার চোখেমুখে ছিল তীব্র ভয়ের ছাপ, যেন সে সদ্য কোনো ভয়ানক মৃত্যুর মুখ থেকে কোনোমতে প্রাণ বাঁচিয়ে ছুটে এসেছে। সে হাঁপাতে হাঁপাতে বলল, \"তোমরা এখনো এখানে দাঁড়িয়ে আছো? সর্বনাশ হয়ে গেছে! আর মাত্র কয়েকটা প্রহর বাকি, এর মধ্যেই আমাদের এই স্থান ত্যাগ করতে হবে!\"",
